class Element{constructor(tag){this.tag=tag;this.children=[];this.attrs={};this.listeners={};this.clientHeight=600;}append(...items){for(const item of items){if(item.parent)item.parent.children.splice(item.parent.children.indexOf(item),1);this.children.push(item);item.parent=this;}}replaceChildren(...items){for(const child of this.children)child.parent=null;this.children=[];this.append(...items);}setAttribute(k,v){this.attrs[k]=v;}addEventListener(k,fn){(this.listeners[k]||=[]).push(fn);}getBoundingClientRect(){return {left:0,top:0,width:800,height:600};}}
class Controls extends T.EventDispatcher{constructor(){super();this.helper=new T.Group();this.axis=null;}getHelper(){return this.helper;}setMode(v){this.mode=v;}setSpace(v){this.space=v;}setSize(v){this.size=v;}setTranslationSnap(){}setRotationSnap(){}setScaleSnap(){}attach(o){this.object=o;}detach(){this.object=null;}}

test('Move with mouse defaults on and switches to the standard object move gizmo without editing the plant',()=>{
 const s=setup();try{const e=s.editor;e.open(s.part);const original=structuredClone(e.draft);assert.equal(s.field('Move with mouse').checked,true);assert.equal(e.moveControl.hidden,false);assert.ok(!all(e.panel).includes(s.field('Move with mouse')),'checkbox is outside the sidebar');assert.equal(e.controls.enabled,false);assert.equal(e.controls.getHelper().visible,false);
 const toggle=s.field('Move with mouse');toggle.checked=false;toggle.onchange();assert.equal(e.moveWithMouse,false);assert.equal(e.controls.enabled,true);assert.equal(e.controls.getHelper().visible,true);assert.equal(e.controls.space,'world');assert.equal(e.controls.size,.8);assert.deepEqual(e.draft,original);assert.equal(s.action('undo').disabled,true);
 const m=e.handles.children.find(m=>m.userData.floraHandle.branch===e.selection.branch&&m.userData.floraHandle.index===e.selection.index),ndc=m.getWorldPosition(new T.Vector3()).project(s.camera),event={button:0,clientX:(ndc.x+1)*400,clientY:(1-ndc.y)*300,preventDefault(){},stopImmediatePropagation(){}};
 for(const fn of s.canvas.listeners.pointerdown)fn(event);for(const fn of s.canvas.listeners.pointermove)fn({...event,clientX:event.clientX+35});for(const fn of s.canvas.listeners.pointerup)fn({...event,clientX:event.clientX+35});assert.deepEqual(e.draft,original,'direct node dragging is off');
 const c=e.controls;c.dispatchEvent({type:'dragging-changed',value:true});c.object.position.x+=.2;c.dispatchEvent({type:'objectChange'});c.dispatchEvent({type:'dragging-changed',value:false});assert.notDeepEqual(e.draft,original);e.undo();assert.deepEqual(e.draft,original);assert.equal(s.field('Move with mouse').checked,false);e.undo(true);assert.notDeepEqual(e.draft,original);
 e.setMode('rotate');assert.equal(e.moveControl.hidden,true);assert.equal(c.enabled,true);assert.equal(e.widgets.children.length,0);e.setMode('translate');assert.equal(s.field('Move with mouse').checked,false);e.setMoveWithMouse(true);assert.equal(c.enabled,false);e.close();assert.equal(e.moveControl.hidden,true);assert.equal(c.enabled,false);assert.equal(c.getHelper().visible,false);
 }finally{s.cleanup();}
});

test('standard gizmo gestures cancel with Escape, Undo, or lost capture and release navigation',()=>{
 const s=setup();try{const e=s.editor;e.open(s.part);e.setMoveWithMouse(false);
 for(const cancel of ['Escape','z','lostpointercapture']){const original=structuredClone(e.draft),c=e.controls;c.dispatchEvent({type:'dragging-changed',value:true});c.object.position.x+=.2;c.dispatchEvent({type:'objectChange'});assert.notDeepEqual(e.draft,original);assert.equal(s.orbit.enabled,false);
 if(cancel==='lostpointercapture')for(const fn of s.canvas.listeners.lostpointercapture)fn({});else for(const fn of window.listeners.keydown)fn({key:cancel,ctrlKey:cancel==='z',target:{},preventDefault(){},stopImmediatePropagation(){}});
 assert.deepEqual(e.draft,original);assert.equal(e.dragging,false);assert.equal(s.orbit.enabled,true);assert.equal(c.enabled,true);assert.equal(s.action('undo').disabled,true);
 }
 }finally{s.cleanup();}
});

test('the first placed piece gives a new generic plant a useful name and remains undoable',()=>{
 const s=setup();try{const e=s.editor;e.open(makePart('flora',{name:'Plant',flora:defaultFlora()}));e.beginAssetPlacement('curled-fern-fiddlehead');assert.equal(e.placingAsset,'curled-fern-fiddlehead');e.endAssetDrag();assert.equal(e.placingAsset,null);e.addAsset('curled-fern-fiddlehead');assert.equal(e.draft.name,'Curled Fern Fiddlehead');e.undo();assert.equal(e.draft.name,'Plant');assert.equal(e.draft.flora.organs.length,0);}finally{s.cleanup();}
});

test('Flora selection outline follows the exact selected part and disappears on deselect and exit',()=>{
 const s=setup();try{const e=s.editor;e.open(s.part);const leaf=e.draft.flora.organs[0];e.select({organ:leaf.id,branch:leaf.branch});const target=e.preview.children.find(g=>g.userData.floraOrgan===leaf.id);e.preview.updateMatrixWorld(true);const bounds=new T.Box3().setFromObject(target),outline=e.selectionOutline;assert.equal(outline.visible,true);outline.geometry.computeBoundingBox();assert.ok(outline.geometry.boundingBox.min.distanceTo(bounds.min)<1e-5);assert.ok(outline.geometry.boundingBox.max.distanceTo(bounds.max)<1e-5);assert.equal(outline.material.depthTest,false);e.deselect();assert.equal(outline.visible,false);e.select({organ:leaf.id,branch:leaf.branch});assert.equal(outline.visible,true);e.close();assert.equal(outline.visible,false);}
 finally{s.cleanup();}
});

test('curled fern sliders update live, undo once per gesture, cancel, and save both shape controls',()=>{
 const s=setup();try{const e=s.editor,f=defaultFlora(),fern=addFloraAsset(f,f.branches[0].id,'curled-fern-fiddlehead');e.open(makePart('flora',{flora:f}));e.select({organ:fern.id,branch:fern.branch});assert.equal(s.field('Attachment point'),undefined);assert.ok(s.field('Curl'));assert.ok(s.field('Leaf budding'));assert.equal(s.field('Curl').value,1);assert.equal(s.field('Leaf budding').value,0);
  const localMesh=()=>e.preview.children.find(g=>g.userData.floraOrgan===fern.id).children[0],original=[...localMesh().geometry.attributes.position.array],curl=s.field('Curl');curl.value=.6;curl.oninput();curl.value=.2;curl.oninput();assert.notDeepEqual([...localMesh().geometry.attributes.position.array],original);curl.onchange();assert.equal(e.draft.flora.organs[0].morphs.curl,.2);e.undo();assert.equal(e.draft.flora.organs[0].morphs,undefined);e.undo(true);assert.equal(e.draft.flora.organs[0].morphs.curl,.2);
  const leaves=s.field('Leaf budding');leaves.value=.8;leaves.oninput();leaves.onchange();assert.deepEqual(e.draft.flora.organs[0].morphs,{curl:.2,budding:.8});const cancel=s.field('Curl');cancel.value=.9;cancel.oninput();for(const fn of cancel.listeners.pointercancel)fn({});assert.deepEqual(e.draft.flora.organs[0].morphs,{curl:.2,budding:.8});e.finish();assert.deepEqual(s.saved.flora.organs[0].morphs,{curl:.2,budding:.8});assert.doesNotThrow(()=>validateProject(JSON.parse(JSON.stringify({format:'open-building-studio',version:1,name:'Fern',parts:[s.saved]}))));
 }finally{s.cleanup();}
});
test('deleting the last part of an existing plant can be finished as a scene deletion',()=>{const s=setup();try{s.editor.open(s.part);s.editor.select({branch:s.editor.draft.flora.branches[0].id,index:0});s.editor.removeSelected();assert.equal(s.action('finish').disabled,false);s.editor.finish();assert.equal(s.savedOptions.deleted,true);assert.equal(s.editor.active,false);}finally{s.cleanup();}});

test('native modal shortcuts cannot delete or finish the plant behind the dialog',()=>{const s=setup();try{s.editor.open(s.part);const before=JSON.stringify(s.editor.draft);document.querySelector=selector=>selector==='dialog[open]'?{open:true}:null;for(const key of ['Delete','Backspace','Escape','z','y'])for(const fn of window.listeners.keydown)fn({key,ctrlKey:['z','y'].includes(key),target:{matches(){return false;}},preventDefault(){throw Error('The scene intercepted a dialog key.');},stopImmediatePropagation(){throw Error('The scene intercepted a dialog key.');}});assert.equal(JSON.stringify(s.editor.draft),before);assert.equal(s.editor.active,true);assert.equal(s.saved,null);}finally{s.cleanup();}});
test('Delete and Undo shortcuts work after selecting a part in the dropdown',()=>{const s=setup();try{const e=s.editor;e.open(s.part);const leaf=e.draft.flora.organs[0];e.select({organ:leaf.id,branch:leaf.branch});const before=e.draft.flora.organs.length,send=(key,ctrlKey=false)=>{let prevented=false;for(const fn of window.listeners.keydown)fn({key,ctrlKey,target:{matches:selector=>selector.includes('select')},preventDefault(){prevented=true;},stopImmediatePropagation(){}});assert.equal(prevented,true);};send('Delete');assert.equal(e.draft.flora.organs.length,before-1);send('z',true);assert.equal(e.draft.flora.organs.length,before);send('y',true);assert.equal(e.draft.flora.organs.length,before-1);}finally{s.cleanup();}});
test('the last procedural part and the root trunk can be deleted and restored with Undo',()=>{const s=setup();try{const f=defaultFlora();addFloraAsset(f,f.branches[0].id,'flora-bent-twig');const e=s.editor;e.open(makePart('flora',{flora:f}));e.removeSelected();assert.equal(e.draft.flora.organs.length,0);assert.equal(s.action('finish').disabled,true);e.undo();assert.equal(e.draft.flora.organs.length,1);e.open(s.part);e.select({branch:e.draft.flora.branches[0].id,index:0});e.removeSelected();assert.equal(e.draft.flora.branches.length,1);assert.equal(e.draft.flora.branches[0].anchor,true);assert.equal(e.draft.flora.organs.length,0);e.undo();assert.equal(e.draft.flora.branches.length,4);assert.equal(e.draft.flora.organs.length,9);}finally{s.cleanup();}});
test('the first clicked catalogue part has an undoable creation step',()=>{const s=setup();try{const previous=makePart('flora',{flora:defaultFlora()}),placed=structuredClone(previous);addFloraAsset(placed.flora,placed.flora.branches[0].id,'flora-bent-twig');s.editor.open(placed,{previous});assert.equal(s.action('undo').disabled,false);s.editor.undo();assert.equal(s.editor.draft.flora.organs.length,0);assert.equal(s.action('redo').disabled,false);s.editor.undo(true);assert.equal(s.editor.draft.flora.organs[0].asset,'flora-bent-twig');}finally{s.cleanup();}});
test('the first sidebar drop previews and places a part on the floor away from the invisible origin',()=>{const s=setup();try{const e=s.editor,p=makePart('flora',{flora:defaultFlora()}),event={clientX:650,clientY:450,dataTransfer:{},preventDefault(){},stopPropagation(){}};e.beginAssetDrag('flora-bent-twig',p);for(const fn of s.canvas.listeners.dragover)fn(event);assert.equal(e.active,true);assert.equal(e.dropTarget.free,true);assert.ok(e.ghost);assert.equal(event.dataTransfer.dropEffect,'copy');const position=[...e.draft.position];assert.ok(position.some(x=>Math.abs(x)>.1));assert.equal(position[1],0);for(const fn of s.canvas.listeners.drop)fn(event);assert.equal(e.draft.flora.organs.length,1);assert.equal(e.draft.flora.organs[0].asset,'flora-bent-twig');assert.deepEqual(e.draft.position,position);assert.ok(e.connections.visible);assert.equal(e.connections.children.length,0);assert.equal(p.flora.organs.length,0);e.finish();assert.deepEqual(s.saved.position,position);}finally{s.cleanup();}});
test('surface parts expose one part control and authored morphs, with no joints or attachment dropdown',()=>{
 const s=setup();try{const f=defaultFlora(),root=addFloraAsset(f,f.branches[0].id,'flora-bent-twig'),e=s.editor;e.open(makePart('flora',{flora:f}));
  assert.equal(e.connections.children.length,0);assert.equal(s.field('Attachment point'),undefined);
  assert.equal(e.handles.children.filter(m=>m.userData.floraMarkerKind==='part').length,1);
  assert.ok(e.handles.children.every(m=>['part','shape'].includes(m.userData.floraMarkerKind)));
  e.select({organ:root.id,branch:root.branch,socket:'body:2'});assert.equal(e.selection.socket,undefined);
  e.beginAssetDrag('flora-elbow-branch');assert.ok(e.connections.children.every(m=>m.userData.floraConnection.organ!==root.id));e.endAssetDrag();
  e.select({...floraSurfaceTarget(f,{organ:root.id,branch:root.branch,at:0,surface:{mesh:0,triangle:10,bary:[.2,.3,.5]}})});e.addAsset('flora-ginkgo-leaf');assert.ok(e.draft.flora.organs.at(-1).pin);assert.equal(e.draft.flora.organs.at(-1).parentOrgan,root.id);
 }finally{s.cleanup();}
});
test('foliage drags reuse plant geometry and overlays instead of rebuilding the skin',()=>{const s=setup();try{const e=s.editor;e.open(s.part);const leaf=e.draft.flora.organs[0];e.select({branch:leaf.branch,organ:leaf.id});const originalOffset=[...leaf.offset],preview=e.preview,skin=preview.children.find(m=>m.isMesh),skinGeometry=skin.geometry,attachment=preview.children.find(g=>g.userData.floraOrgan===leaf.id),leafGeometry=attachment.children[0].geometry,handles=[...e.handles.children],c=e.controls;c.dispatchEvent({type:'dragging-changed',value:true});const samples=[];for(let i=0;i<40;i++){c.object.position.x=i*.01;const start=performance.now();c.dispatchEvent({type:'objectChange'});samples.push(performance.now()-start);assert.equal(e.preview,preview);assert.equal(skin.geometry,skinGeometry);assert.equal(attachment.children[0].geometry,leafGeometry);assert.deepEqual(e.handles.children,handles);assert.ok(new T.Vector3().setFromMatrixPosition(attachment.matrix).distanceTo(floraOrganPosition(e.draft.flora,leaf))<1e-6);}samples.sort((a,b)=>a-b);console.log('Foliage drag event median: '+samples[20].toFixed(2)+' ms');c.dispatchEvent({type:'dragging-changed',value:false});assert.equal(e.preview.userData.floraLive,true);e.undo();assert.deepEqual(e.draft.flora.organs[0].offset,originalOffset);}finally{s.cleanup();}});
test('woody manipulation retains complete part meshes before, during and after dragging',()=>{const s=setup();try{const f=defaultFlora(),root=addFloraAsset(f,f.branches[0].id,'flora-taproot'),child=addFloraAsset(f,root.branch,'flora-elbow-branch',0,0,{organ:root.id,socket:'joint:1'}),e=s.editor;e.open(makePart('flora',{flora:f}));e.select({organ:root.id,branch:root.branch});const c=e.controls;c.dispatchEvent({type:'dragging-changed',value:true});assert.equal(e.preview.userData.floraLive,true);const preview=e.preview,raw=preview.children.find(g=>g.userData.floraOrgan===root.id),branch=preview.children.find(g=>g.userData.floraBranch===child.id),geometry=branch.geometry;for(let i=0;i<10;i++){c.object.position.x=i*.05;c.dispatchEvent({type:'objectChange'});assert.equal(e.preview,preview);assert.equal(branch.geometry,geometry);assert.ok(Math.abs(raw.matrix.elements[12]-i*.05)<1e-6);}c.dispatchEvent({type:'dragging-changed',value:false});assert.equal(e.preview.userData.floraLive,true);assert.ok(e.preview.children.some(m=>m.userData.floraOrgan===root.id));assert.ok(e.preview.children.some(m=>m.userData.floraBranch===child.id));e.undo();assert.deepEqual(e.draft.flora.organs[0].offset,[0,0,0]);}finally{s.cleanup();}});
test('palette clicks build on the selected procedural part and parent transforms carry children with undo',()=>{const s=setup();try{const f=defaultFlora(),root=addFloraAsset(f,f.branches[0].id,'flora-taproot'),e=s.editor;e.open(makePart('flora',{flora:f}));e.addAsset(PROCEDURAL_FLORA.find(a=>a.category==='Leaves').id);const leaf=e.draft.flora.organs.at(-1);assert.equal(leaf.parentOrgan,root.id);assert.ok(leaf.pin);const old=floraOrganPosition(e.draft.flora,leaf);e.select({organ:root.id,branch:root.branch});e.setMode('translate');const c=e.controls;c.dispatchEvent({type:'dragging-changed',value:true});c.object.position.x+=1;c.dispatchEvent({type:'objectChange'});c.dispatchEvent({type:'dragging-changed',value:false});assert.ok(floraOrganPosition(e.draft.flora,leaf).distanceTo(old.clone().add(new T.Vector3(1,0,0)))<1e-6);e.undo();assert.ok(floraOrganPosition(e.draft.flora,e.draft.flora.organs.at(-1)).distanceTo(old)<1e-6);e.select({organ:root.id,branch:root.branch});s.action('remove').onclick();assert.equal(e.draft.flora.organs.length,0);e.undo();assert.equal(e.draft.flora.organs.length,2);e.finish();assert.equal(s.saved.flora.organs.at(-1).parentOrgan,root.id);}finally{s.cleanup();}});
test('dragging onto an procedural socket uses the same transform for ghost and saved attachment',()=>{const s=setup();try{const f=defaultFlora(),root=addFloraAsset(f,f.branches[0].id,'flora-taproot'),e=s.editor;root.rotation=[.2,.6,.3];root.scale=[1.2,.9,1.3];e.open(makePart('flora',{flora:f,position:[3,2,1],rotation:[.2,.6,-.1],scale:[2,1.5,1]}));e.beginAssetDrag(PROCEDURAL_FLORA.find(a=>a.assembly).id);const target=e.connections.children.find(m=>m.userData.floraConnection.organ===root.id&&m.userData.floraConnection.socket==='joint:0'),point=target.position.clone().project(s.camera),event={clientX:(point.x+1)*400,clientY:(1-point.y)*300,dataTransfer:{},preventDefault(){},stopPropagation(){}};for(const fn of s.canvas.listeners.dragover)fn(event);assert.equal(e.dropTarget.organ,root.id);const ghost=e.ghost.children[0].matrix.clone();for(const fn of s.canvas.listeners.drop)fn(event);const added=e.draft.flora.organs.at(-1),actual=floraOrganMatrix(e.draft.flora,added);assert.equal(added.parentOrgan,root.id);for(let i=0;i<16;i++)assert.ok(Math.abs(ghost.elements[i]-actual.elements[i])<1e-6);e.undo();assert.equal(e.draft.flora.organs.length,1);}finally{s.cleanup();}});
const all=e=>[e,...e.children.flatMap(all)];
test('SWBF2 surface detail is selectable without a selected joint, undoable, and saved with the plant',()=>{
 const s=setup();try{
  const e=s.editor;e.open(s.part);const joints=structuredClone(e.draft.flora.branches),organs=structuredClone(e.draft.flora.organs),old=e.draft.flora.detail;
  let input=s.field('Plant mesh detail');assert.ok(input.children.some(o=>o.value==='swbf2'&&o.textContent==='SWBF2'));
  input.value='swbf2';input.onchange();assert.equal(e.draft.flora.detail,'swbf2');assert.deepEqual(e.draft.flora.branches,joints);assert.deepEqual(e.draft.flora.organs,organs);
  e.undo();assert.equal(e.draft.flora.detail,old);e.undo(true);assert.equal(e.draft.flora.detail,'swbf2');
  e.select({});assert.ok(s.field('Plant mesh detail'));e.finish();assert.equal(s.saved.flora.detail,'swbf2');
  validateProject({format:'open-building-studio',version:1,name:'SWBF2 surface',parts:[s.saved]});
 }finally{s.cleanup();}
});
test('a root-only plant selects its root and has no automatic trunk joints',()=>{const s=setup();try{const f=defaultFlora(),root=addFloraAsset(f,f.branches[0].id,'flora-taproot',.8);s.editor.open(makePart('flora',{flora:f}));assert.equal(s.editor.selection.organ,root.id);assert.equal(root.at,0);assert.equal(s.editor.handles.children.length,1);assert.equal(s.editor.handles.children[0].userData.floraHandle.organ,root.id);assert.equal(s.field('Joint thickness'),undefined);s.editor.beginAssetDrag('flora-taproot');assert.ok(s.editor.connections.children.length>=1);assert.ok(s.editor.connections.children.every(m=>m.userData.floraConnection.organ===root.id));assert.ok(s.field('Attachment point')); s.editor.endAssetDrag();s.editor.finish();assert.equal(s.saved.flora.branches.filter(b=>!b.anchor).length,0);}finally{s.cleanup();}});
test('large attachment origin spheres remain bounded when scaled and zoomed',()=>{const s=setup();try{s.editor.open(s.part);s.editor.addAsset('flora-antler-root');s.editor.setMode('scale');const c=s.editor.controls;c.dispatchEvent({type:'dragging-changed',value:true});c.object.scale.set(10,10,10);c.dispatchEvent({type:'objectChange'});c.dispatchEvent({type:'dragging-changed',value:false});for(const position of [[5,4,7],[6,5,8]]){s.camera.position.fromArray(position);s.camera.lookAt(3,3,1);s.camera.updateMatrixWorld(true);s.orbit.dispatchEvent({type:'change'});for(const m of s.editor.handles.children){const depth=-m.position.clone().applyMatrix4(s.camera.matrixWorldInverse).z,unit=depth*Math.tan(s.camera.fov*Math.PI/360)*2/600,max=Math.max(...[0,1,2].map(i=>new T.Vector3().setFromMatrixColumn(m.matrixWorld,i).length()));assert.ok(max/unit<=36.001);assert.ok(max/unit>=5.999);}}}finally{s.cleanup();}});
test('dragging a joint part previews an exact tip connection, drops once, and undoes cleanly',()=>{const s=setup();try{const e=s.editor;e.open(s.part);const asset=PROCEDURAL_FLORA.find(a=>a.profile),count=e.draft.flora.branches.length,targetBranch=e.draft.flora.branches[1].id;e.beginAssetDrag(asset.id);assert.equal(e.connections.visible,true);assert.equal(e.handles.visible,false);assert.equal(s.orbit.enabled,false);const target=e.connections.children.find(m=>m.userData.floraConnection.branch===targetBranch&&m.userData.floraConnection.at===1),point=target.position.clone().project(s.camera),event={clientX:(point.x+1)*400,clientY:(1-point.y)*300,dataTransfer:{},preventDefault(){},stopPropagation(){}};for(const fn of s.canvas.listeners.dragover)fn(event);assert.deepEqual(e.dropTarget,{branch:targetBranch,at:1});assert.ok(e.ghost);assert.equal(e.draft.flora.branches.length,count);const ghost=Array.from(e.ghost.children[0].geometry.attributes.position.array);for(const fn of s.canvas.listeners.drop)fn(event);const added=e.draft.flora.branches.at(-1);assert.equal(e.draft.flora.branches.length,count+1);assert.equal(added.parent,targetBranch);assert.equal(added.at,1);assert.equal(added.profile,asset.id);assert.equal(added.id,e.selection.branch);const mesh=e.preview.children.find(m=>m.userData.floraBranch===added.id);const positions=mesh.geometry.attributes.position;for(let i=0;i<positions.count;i++){const p=new T.Vector3().fromBufferAttribute(positions,i).applyMatrix4(mesh.matrix);assert.ok(p.distanceTo(new T.Vector3().fromArray(ghost,i*3))<1e-5);}e.undo();assert.equal(e.draft.flora.branches.length,count);}finally{s.cleanup();}});
test('invalid drops and cancelled drags do not add parts; idle drag opens the staged plant on entering the canvas',()=>{const s=setup();try{const e=s.editor,asset=PROCEDURAL_FLORA.find(a=>a.profile),event={clientX:-1000,clientY:-1000,dataTransfer:{},preventDefault(){},stopPropagation(){}};e.beginAssetDrag(asset.id,s.part);assert.equal(e.active,false);for(const fn of s.canvas.listeners.dragenter)fn(event);assert.equal(e.active,true);assert.equal(e.dropTarget,null);const count=e.draft.flora.branches.length;for(const fn of s.canvas.listeners.drop)fn(event);assert.equal(e.draft.flora.branches.length,count);e.beginAssetDrag(asset.id);e.endAssetDrag();assert.equal(e.connections.visible,true);assert.equal(e.ghost,null);assert.equal(e.draft.flora.branches.length,count);}finally{s.cleanup();}});
test('flora origin outlines grow with joint thickness and procedural-part scaling',()=>{const s=setup();try{s.camera.position.set(15,12,20);s.camera.lookAt(0,1,0);s.camera.updateMatrixWorld(true);const e=s.editor;e.open(s.part);const joint=()=>e.handles.children.find(m=>!m.userData.floraHandle.organ&&m.userData.floraHandle.branch===e.selection.branch&&m.userData.floraHandle.index===1),extent=m=>new T.Vector3(1,0,0).applyMatrix4(m.matrixWorld).distanceTo(m.getWorldPosition(new T.Vector3()));assert.ok(Math.abs(extent(joint())-.4)<1e-6);const input=s.field('Joint thickness');input.value=.4;input.onchange();assert.ok(Math.abs(extent(joint())-.8)<1e-6);e.open(makePart('flora',{flora:defaultFlora()}));e.addAsset('flora-root-crown');const marker=()=>e.handles.children.find(m=>m.userData.floraHandle.organ===e.selection.organ),before=extent(marker());e.setMode('scale');e.controls.dispatchEvent({type:'dragging-changed',value:true});e.controls.object.scale.multiplyScalar(2);e.controls.dispatchEvent({type:'objectChange'});e.controls.dispatchEvent({type:'dragging-changed',value:false});assert.ok(extent(marker())>before);assert.ok(extent(marker())<=before*2+1e-6);assert.equal(marker().material.wireframe,true);}finally{s.cleanup();}});
test('catalogue additions select the new attachment or muscle branch and remain locally undoable',()=>{const s=setup();try{s.editor.open(s.part);for(const action of ['branch','leaf','frond','flower','extend'])assert.equal(s.action(action),undefined);const leaf=PROCEDURAL_FLORA.find(a=>a.category==='Leaves'),profile=PROCEDURAL_FLORA.find(a=>a.profile),organs=s.editor.draft.flora.organs.length,branches=s.editor.draft.flora.branches.length;s.editor.addAsset(leaf.id);assert.equal(s.editor.draft.flora.organs.length,organs+1);assert.equal(s.editor.draft.flora.organs.at(-1).id,s.editor.selection.organ);s.editor.addAsset(profile.id);assert.equal(s.editor.draft.flora.branches.length,branches+1);assert.equal(s.editor.draft.flora.branches.at(-1).id,s.editor.selection.branch);s.editor.undo();assert.equal(s.editor.draft.flora.branches.length,branches);s.editor.finish();assert.equal(s.saved.flora.organs.at(-1).asset,leaf.id);assert.equal(s.part.flora.organs.length,organs);}finally{s.cleanup();}});
function setup(){const priorDocument=globalThis.document,priorWindow=globalThis.window;globalThis.document={createElement:tag=>new Element(tag)};globalThis.window=new Element('window');const scene=new T.Scene(),camera=new T.PerspectiveCamera(45,800/600,.1,100);camera.position.set(5,4,7);camera.lookAt(0,1,0);camera.updateMatrixWorld(true);const canvas=new Element('canvas'),viewport=new Element('div'),orbit=new T.EventDispatcher();orbit.enabled=true;const part=makePart('flora',{flora:testPlant(),position:[3,2,1],rotation:[.2,.6,-.1],scale:[2,1.5,1]}),source=buildPart(part);scene.add(source);let saved=null,savedOptions=null,closed=0;const editor=createFloraEditor({scene,camera,canvas,viewport,orbit,meshes:()=>new Map([[part.id,source]]),prepare(){},save:(p,options)=>{saved=p;savedOptions=options;},onClose:()=>closed++,invalidate(){},transformFactory:()=>new Controls()});const action=key=>all(editor.panel).find(e=>e.attrs['data-flora-action']===key),field=name=>[...all(editor.panel),...all(editor.moveControl)].find(e=>e.attrs['aria-label']===name);return {editor,part,source,scene,camera,canvas,orbit,action,field,get saved(){return saved;},get savedOptions(){return savedOptions;},get closed(){return closed;},cleanup(){editor.close();disposePart(source);globalThis.document=priorDocument;globalThis.window=priorWindow;}};}
test('flora editor keeps original unchanged until Finish and exposes each joint and attachment',()=>{const s=setup();try{s.editor.open(s.part);assert.equal(s.source.visible,false);const count=s.editor.handles.children.length;s.editor.addAsset(PROCEDURAL_FLORA.find(a=>a.profile).id);s.editor.addAsset(PROCEDURAL_FLORA.find(a=>a.category==='Leaves').id);assert.ok(s.editor.handles.children.length>0);assert.ok(s.editor.handles.children.filter(m=>m.userData.floraMarkerKind!=='joint').every(m=>m.userData.floraHandle.organ===s.editor.selection.organ));assert.equal(s.part.flora.branches.length,4);assert.equal(s.editor.draft.flora.branches.length,5);s.action('finish').onclick();assert.equal(s.editor.active,false);assert.equal(s.source.visible,true);assert.equal(s.saved.flora.branches.length,5);assert.equal(s.saved.flora.organs.length,10);assert.equal(s.editor.handles.children.length,0);}finally{s.cleanup();}});
test('joint movement moves attachments, scaling changes radius, rotation transforms a complete branch; undo is local',()=>{const s=setup();try{const e=s.editor;e.open(s.part);const root=e.draft.flora.branches[0],controls=e.controls,old=root.points[1][0];controls.dispatchEvent({type:'dragging-changed',value:true});controls.object.position.x+=.5;controls.dispatchEvent({type:'objectChange'});controls.dispatchEvent({type:'dragging-changed',value:false});assert.equal(e.draft.flora.branches[0].points[1][0],old+.5);assert.equal(s.part.flora.branches[0].points[1][0],old);e.setMode('scale');controls.dispatchEvent({type:'dragging-changed',value:true});controls.object.scale.multiplyScalar(2);controls.dispatchEvent({type:'objectChange'});controls.dispatchEvent({type:'dragging-changed',value:false});assert.equal(e.draft.flora.branches[0].radii[1],.4);e.undo();assert.equal(e.draft.flora.branches[0].radii[1],.2);e.undo(true);assert.equal(e.draft.flora.branches[0].radii[1],.4);e.select({branch:e.draft.flora.branches[1].id,index:1});const original=structuredClone(e.draft.flora.branches[1].points);e.setMode('rotate');controls.dispatchEvent({type:'dragging-changed',value:true});controls.object.rotation.y=.8;controls.dispatchEvent({type:'objectChange'});controls.dispatchEvent({type:'dragging-changed',value:false});assert.deepEqual(e.draft.flora.branches[1].points,original);assert.ok(e.draft.flora.branches[1].jointRotations[1]);assert.deepEqual(e.draft.flora.branches[1].points[0],[0,0,0]);e.finish();validateProject({format:'open-building-studio',version:1,name:'Flora',parts:[s.saved]});}finally{s.cleanup();}});
test('foliage can be moved, uniformly sized and rotated individually without detaching from its parent',()=>{const s=setup();try{const e=s.editor;e.open(s.part);e.addAsset(PROCEDURAL_FLORA.find(a=>a.category==='Leaves').id);const chosen=e.selection.organ,o=e.draft.flora.organs.find(o=>o.id===chosen),branch=o.branch,controls=e.controls;o.scale=[1,1,1];e.select({organ:chosen,branch});controls.dispatchEvent({type:'dragging-changed',value:true});controls.object.position.x+=1;controls.dispatchEvent({type:'objectChange'});controls.dispatchEvent({type:'dragging-changed',value:false});assert.ok(Math.abs(e.draft.flora.organs.find(o=>o.id===chosen).offset[0]-1)<1e-6);e.setMode('scale');controls.dispatchEvent({type:'dragging-changed',value:true});controls.object.scale.set(.5,2,1);controls.dispatchEvent({type:'objectChange'});controls.dispatchEvent({type:'dragging-changed',value:false});assert.deepEqual(e.draft.flora.organs.find(o=>o.id===chosen).scale,[2,2,2]);assert.equal(e.draft.flora.organs.find(o=>o.id===chosen).branch,branch);s.action('cancel').onclick();assert.equal(s.saved,null);assert.equal(s.source.visible,true);}finally{s.cleanup();}});
test('ray clicks select joints in transformed plants and invalid moves roll back safely',()=>{const s=setup();try{const e=s.editor;e.open(s.part);const marker=e.handles.children[2],ndc=marker.position.clone().project(s.camera);let stopped=false;for(const fn of s.canvas.listeners.pointerdown)fn({button:0,clientX:(ndc.x+1)*400,clientY:(1-ndc.y)*300,preventDefault(){},stopImmediatePropagation(){stopped=true;}});assert.equal(stopped,true);assert.equal(e.selection.index,marker.userData.floraHandle.index);e.select({branch:e.draft.flora.branches[0].id,index:1});const old=structuredClone(e.draft.flora);e.controls.dispatchEvent({type:'dragging-changed',value:true});e.controls.object.position.set(...e.draft.flora.branches[0].points[0]);e.controls.dispatchEvent({type:'objectChange'});e.controls.dispatchEvent({type:'dragging-changed',value:false});assert.deepEqual(e.draft.flora,old);assert.equal(s.orbit.enabled,true);}finally{s.cleanup();}});
test('single-axis shrinking reduces joint thickness and branch removal clears dependent foliage',()=>{const s=setup();try{const e=s.editor;e.open(s.part);e.setMode('scale');e.controls.dispatchEvent({type:'dragging-changed',value:true});e.controls.object.scale.x=.08;e.controls.dispatchEvent({type:'objectChange'});e.controls.dispatchEvent({type:'dragging-changed',value:false});assert.equal(e.draft.flora.branches[0].radii[1],.08);e.select({branch:e.draft.flora.branches[1].id,index:1});const id=e.selection.branch;s.action('remove-branch').onclick();assert.ok(!e.draft.flora.branches.some(b=>b.id===id));assert.ok(!e.draft.flora.organs.some(o=>o.branch===id));e.finish();assert.equal(s.saved.flora.branches.length,3);}finally{s.cleanup();}});

test('body preset joints control their own sections and carry attachments through undo and save',()=>{const s=setup();try{const f=defaultFlora(),root=addFloraAsset(f,f.branches[0].id,'flora-forked-bough'),e=s.editor;e.open(makePart('flora',{flora:f,position:[3,2,1],rotation:[.2,.6,-.1],scale:[2,1.5,1]}));const point=e.connections.children.find(m=>m.userData.floraConnection.socket==='joint:2'),ndc=point.position.clone().project(s.camera);e.controls.axis='X';for(const fn of s.canvas.listeners.pointerdown)fn({button:0,clientX:(ndc.x+1)*400,clientY:(1-ndc.y)*300,preventDefault(){},stopImmediatePropagation(){}});assert.equal(e.selection.socket,'joint:2');const socket=floraSockets(root.asset).find(s=>s.id==='joint:2');assert.deepEqual(e.controls.object.position.toArray(),socket.point);const originalOffset=e.draft.flora.organs[0].offset.slice(),originalScale=e.draft.flora.organs[0].scale.slice();e.addAsset('flora-ginkgo-leaf');const leaf=e.draft.flora.organs.at(-1),leafBefore=floraOrganPosition(e.draft.flora,leaf);e.select({organ:root.id,branch:root.branch,socket:socket.id});e.controls.dispatchEvent({type:'dragging-changed',value:true});const mesh=e.preview.children.find(c=>c.userData.floraOrgan===root.id).children[0],array=mesh.geometry.getAttribute('position').array,positions=Array.from(array);e.controls.object.position.x+=.5;e.controls.dispatchEvent({type:'objectChange'});assert.equal(mesh.geometry.userData.floraBodyVolume,true);assert.notEqual(mesh.geometry.getAttribute('position').array,array);assert.notDeepEqual(Array.from(mesh.geometry.getAttribute('position').array),positions);assert.deepEqual(e.draft.flora.organs[0].offset,originalOffset);assert.ok(floraOrganPosition(e.draft.flora,leaf).distanceTo(leafBefore)>.1);e.controls.dispatchEvent({type:'dragging-changed',value:false});e.undo();assert.equal(e.draft.flora.organs[0].controls,undefined);e.undo(true);e.select({organ:root.id,branch:root.branch,socket:socket.id});for(const mode of ['scale','rotate']){e.setMode(mode);e.controls.dispatchEvent({type:'dragging-changed',value:true});if(mode==='scale')e.controls.object.scale.set(1.5,1,1);else e.controls.object.rotation.z=.4;e.controls.dispatchEvent({type:'objectChange'});e.controls.dispatchEvent({type:'dragging-changed',value:false});}assert.deepEqual(e.draft.flora.organs[0].scale,originalScale);assert.deepEqual(e.draft.flora.organs[0].rotation,[0,0,0]);assert.deepEqual(e.draft.flora.organs[0].controls[socket.id].scale,[1.5,1.5,1.5]);assert.equal(e.draft.flora.organs[0].controls[socket.id].rotation[2],.4);e.finish();validateProject({format:'open-building-studio',version:1,name:'Edited trunk',parts:[s.saved]});assert.equal(s.saved.flora.organs[0].controls[socket.id].rotation[2],.4);}finally{s.cleanup();}});
test('wood control deformation anchors untouched guides and validates saved controls',()=>{const f=defaultFlora(),o=addFloraAsset(f,f.branches[0].id,'flora-forked-bough'),sockets=floraSockets(o.asset),chosen=sockets.find(s=>s.id==='joint:3');o.controls={[chosen.id]:{offset:[.5,0,0],rotation:[0,0,.3],scale:[1.5,1,1]}};const output=floraDeformPositions(o,sockets.flatMap(s=>s.point));for(const [i,s] of sockets.entries())assert.ok(new T.Vector3().fromArray(output,i*3).distanceTo(new T.Vector3(...floraSocketPose(o,s).point))<1e-5);validateFlora(f);o.controls.bad=o.controls[chosen.id];assert.throws(()=>validateFlora(f));delete o.controls.bad;o.controls[chosen.id].scale=[0,1,1];assert.throws(()=>validateFlora(f));});

test('clicking procedural wood selects its part; Alt wheel resizes without detaching, while ordinary wheel navigates',()=>{const s=setup();try{const f=defaultFlora(),root=addFloraAsset(f,f.branches[0].id,'flora-bent-twig'),e=s.editor;e.open(makePart('flora',{flora:f}));e.select({organ:root.id,branch:root.branch,socket:'body:2'});const mesh=e.pickTargets.children[0],pos=mesh.geometry.getAttribute('position'),index=mesh.geometry.index,ray=new T.Raycaster();let xy;for(let i=0;i<index.count;i+=3){const p=new T.Vector3();for(let j=0;j<3;j++)p.add(new T.Vector3().fromBufferAttribute(pos,index.getX(i+j)));p.divideScalar(3).applyMatrix4(mesh.matrixWorld);const ndc=p.project(s.camera),pointer=new T.Vector2(ndc.x,ndc.y);ray.setFromCamera(pointer,s.camera);if(ray.intersectObjects(e.connections.children,false).length||ray.intersectObjects(e.handles.children,false).length)continue;if(ray.intersectObjects(e.pickTargets.children,false).length){xy={clientX:(ndc.x+1)*400,clientY:(1-ndc.y)*300};break;}}assert.ok(xy);for(const fn of s.canvas.listeners.pointerdown)fn({button:0,...xy,preventDefault(){},stopImmediatePropagation(){}});assert.equal(e.selection.organ,root.id);assert.equal(e.selection.socket,undefined);let consumed=0;const event={...xy,deltaY:-100,altKey:false,preventDefault(){consumed++;},stopImmediatePropagation(){}};for(const fn of s.canvas.listeners.wheel)fn(event);assert.equal(consumed,0);assert.deepEqual(e.draft.flora.organs[0].scale,[1,1,1]);event.altKey=true;for(const fn of s.canvas.listeners.wheel)fn(event);assert.equal(consumed,1);assert.deepEqual(e.draft.flora.organs[0].scale,[1.1,1.1,1.1]);assert.equal(e.draft.flora.organs[0].branch,root.branch);e.undo();assert.deepEqual(e.draft.flora.organs[0].scale,[1,1,1]);e.close();assert.equal(e.pickTargets.children.length,0);}finally{s.cleanup();}});
test('Alt wheel on a body joint resizes only that control and restores with undo',()=>{const s=setup();try{const f=defaultFlora(),root=addFloraAsset(f,f.branches[0].id,'flora-forked-bough'),e=s.editor;e.open(makePart('flora',{flora:f}));const point=e.connections.children.find(m=>m.userData.floraConnection.socket==='joint:2'),ndc=point.position.clone().project(s.camera);let prevented=false;for(const fn of s.canvas.listeners.wheel)fn({clientX:(ndc.x+1)*400,clientY:(1-ndc.y)*300,deltaY:-100,altKey:true,preventDefault(){prevented=true;},stopImmediatePropagation(){}});assert.ok(prevented);assert.equal(e.selection.socket,'joint:2');assert.deepEqual(e.draft.flora.organs[0].scale,[1,1,1]);assert.deepEqual(e.draft.flora.organs[0].controls['joint:2'].scale,[1.1,1.1,1.1]);e.undo();assert.equal(e.draft.flora.organs[0].controls,undefined);}finally{s.cleanup();}});

test('authored shape sliders and handles deform a part locally, reuse buffers, undo and save',()=>{const s=setup();try{const f=defaultFlora(),root=addFloraAsset(f,f.branches[0].id,'flora-bent-twig'),e=s.editor;e.open(makePart('flora',{flora:f}));const slider=s.field('Bend');assert.ok(slider);slider.value=1;slider.oninput();assert.equal(e.dragging,true);assert.equal(e.draft.flora.organs[0].morphs['bend'],1);const mesh=e.preview.children.find(c=>c.userData.floraOrgan===root.id).children[0],buffer=mesh.geometry.getAttribute('position').array;slider.value=.9;slider.oninput();assert.equal(mesh.geometry.getAttribute('position').array,buffer);slider.onchange();assert.equal(e.dragging,false);e.undo();assert.equal(e.draft.flora.organs[0].morphs,undefined);e.select({organ:root.id,branch:root.branch,morph:'bend'});assert.equal(e.controls.showX,false);assert.equal(e.controls.showZ,false);e.controls.dispatchEvent({type:'dragging-changed',value:true});e.controls.object.position.y*=1.5;e.controls.dispatchEvent({type:'objectChange'});e.controls.dispatchEvent({type:'dragging-changed',value:false});assert.ok(e.draft.flora.organs[0].morphs['bend']>.7);assert.deepEqual(e.draft.flora.organs[0].offset,[0,0,0]);e.finish();assert.ok(s.saved.flora.organs[0].morphs['bend']>.7);}finally{s.cleanup();}});
test('a sidebar drop onto bark pins to the exact surface and the ghost agrees with the saved attachment',()=>{const s=setup();try{const f=defaultFlora(),root=addFloraAsset(f,f.branches[0].id,'flora-bent-twig'),e=s.editor;e.open(makePart('flora',{flora:f}));e.beginAssetDrag('flora-ginkgo-leaf');const pick=e.pickTargets.children[0],pos=pick.geometry.getAttribute('position'),index=pick.geometry.index,ray=new T.Raycaster();let event;for(let i=0;i<index.count;i+=3){const point=new T.Vector3();for(let j=0;j<3;j++)point.add(new T.Vector3().fromBufferAttribute(pos,index.getX(i+j)));point.divideScalar(3).applyMatrix4(pick.matrixWorld);const ndc=point.project(s.camera);if(e.connections.children.some(m=>{const p=m.position.clone().project(s.camera);return Math.hypot((p.x-ndc.x)*400,(p.y-ndc.y)*300)<25;}))continue;ray.setFromCamera(new T.Vector2(ndc.x,ndc.y),s.camera);if(ray.intersectObjects(e.pickTargets.children,false).length){event={clientX:(ndc.x+1)*400,clientY:(1-ndc.y)*300,dataTransfer:{},preventDefault(){},stopPropagation(){}};break;}}assert.ok(event);for(const fn of s.canvas.listeners.dragover)fn(event);assert.ok(e.dropTarget.surface);assert.equal(e.dropTarget.organ,root.id);const ghostMatrix=e.ghost.children[0].matrix.clone(),pin=structuredClone(e.dropTarget.surface);for(const fn of s.canvas.listeners.drop)fn(event);const leaf=e.draft.flora.organs.at(-1);assert.deepEqual(leaf.pin,pin);assert.equal(leaf.parentOrgan,root.id);assert.equal(leaf.socket,undefined);assert.ok(floraOrganMatrix(e.draft.flora,leaf).elements.every((x,i)=>Math.abs(x-ghostMatrix.elements[i])<1e-6));e.undo();assert.equal(e.draft.flora.organs.length,1);}finally{s.cleanup();}});
test('dragging a pinned leaf slides along bark, stays attached off the plant, and cancels or undoes as one edit',()=>{
 const s=setup();try{
  const e=s.editor,f=defaultFlora(),root=addFloraAsset(f,f.branches[0].id,'flora-bent-twig');e.open(makePart('flora',{flora:f}));e.select({...floraSurfaceTarget(f,{organ:root.id,branch:root.branch,at:0,surface:{mesh:0,triangle:10,bary:[.2,.3,.5]}})});e.addAsset('flora-ginkgo-leaf');
  const id=e.selection.organ,before=JSON.stringify(e.draft),marker=e.handles.children.find(m=>m.userData.floraMarkerKind==='part'),ndc=marker.getWorldPosition(new T.Vector3()).project(s.camera),start={button:0,clientX:(ndc.x+1)*400,clientY:(1-ndc.y)*300,preventDefault(){},stopImmediatePropagation(){}};
  const end=new T.Vector3(0,1.7,0).applyMatrix4(floraOrganMatrix(e.draft.flora,e.draft.flora.organs[0])).project(s.camera),move={...start,clientX:(end.x+1)*400,clientY:(1-end.y)*300};
  for(const fn of s.canvas.listeners.pointerdown)fn(start);for(const fn of s.canvas.listeners.pointermove)fn(move);
  assert.equal(e.selection.organ,id);const moved=JSON.stringify(e.draft);assert.notEqual(moved,before);assert.equal(e.draft.flora.organs.at(-1).parentOrgan,root.id);assert.deepEqual(e.draft.flora.organs.at(-1).offset,[0,0,0]);
  for(const fn of s.canvas.listeners.pointermove)fn({...move,clientX:-10000,clientY:-10000});assert.equal(JSON.stringify(e.draft),moved);
  for(const fn of s.canvas.listeners.pointercancel)fn(move);assert.equal(JSON.stringify(e.draft),before);
  for(const fn of s.canvas.listeners.pointerdown)fn(start);for(const fn of s.canvas.listeners.pointermove)fn(move);for(const fn of s.canvas.listeners.pointerup)fn(move);assert.notEqual(JSON.stringify(e.draft),before);e.undo();assert.equal(JSON.stringify(e.draft),before);
 }finally{s.cleanup();}
});

test('reattachment previews another parent, carries the subtree, and is one undoable edit',()=>{const s=setup();try{const f=defaultFlora(),a=addFloraAsset(f,f.branches[0].id,'flora-forked-bough'),b=addFloraAsset(f,a.branch,'flora-candelabra-branch',0,0,{organ:a.id,socket:'joint:3'}),leaf=addFloraAsset(f,a.branch,'flora-ginkgo-leaf',0,0,{organ:b.id,socket:'joint:2'}),other=addFloraAsset(f,a.branch,'flora-forked-bough');other.offset=[3,0,0];const e=s.editor;e.open(makePart('flora',{flora:f}));e.select({organ:b.id,branch:b.branch});s.action('reattach').onclick();assert.equal(e.reattaching,b.id);assert.ok(e.connections.children.every(m=>![b.id,leaf.id].includes(m.userData.floraConnection.organ)));const m=e.connections.children.find(m=>m.userData.floraConnection.organ===other.id&&m.userData.floraConnection.socket==='joint:3'),p=m.position.clone().project(s.camera),event={button:0,clientX:(p.x+1)*400,clientY:(1-p.y)*300,preventDefault(){},stopPropagation(){},stopImmediatePropagation(){}};const snapshot=JSON.stringify(e.draft);for(const fn of s.canvas.listeners.pointermove)fn(event);assert.ok(e.ghost);assert.equal(JSON.stringify(e.draft),snapshot);for(const fn of s.canvas.listeners.pointerdown)fn(event);assert.equal(e.reattaching,null);assert.equal(e.draft.flora.organs.find(o=>o.id===b.id).parentOrgan,other.id);assert.equal(e.draft.flora.organs.find(o=>o.id===leaf.id).parentOrgan,b.id);e.undo();assert.equal(e.draft.flora.organs.find(o=>o.id===b.id).parentOrgan,a.id);e.beginReattach();for(const fn of window.listeners.keydown)fn({key:'Escape',target:{},preventDefault(){},stopImmediatePropagation(){}});assert.equal(e.reattaching,null);assert.equal(e.active,true);}finally{s.cleanup();}});

test('part style, insertion and subtree duplication stay in local history',()=>{const s=setup();try{const f=defaultFlora(),root=addFloraAsset(f,f.branches[0].id,'flora-bent-twig'),leaf=addFloraAsset(f,root.branch,'flora-ginkgo-leaf',0,0,{organ:root.id,surface:{mesh:0,triangle:10,bary:[.2,.3,.5]}}),e=s.editor;e.open(makePart('flora',{flora:f}));e.select({organ:leaf.id,branch:leaf.branch});const depth=s.field('Insertion depth');depth.value=.15;depth.onchange();assert.equal(e.draft.flora.organs[1].depth,.15);e.undo();assert.equal(e.draft.flora.organs[1].depth,undefined);e.select({organ:root.id,branch:root.branch});const style=s.field('Part style');style.value='flora-tapered-twig';style.onchange();assert.equal(e.draft.flora.organs[0].asset,'flora-tapered-twig');assert.equal(e.draft.flora.organs[1].parentOrgan,root.id);e.undo();assert.equal(e.draft.flora.organs[0].asset,'flora-bent-twig');e.select({organ:root.id,branch:root.branch});s.action('duplicate-branch').onclick();assert.equal(e.draft.flora.organs.length,4);assert.ok(e.reattaching);e.undo();assert.equal(e.reattaching,null);assert.equal(e.draft.flora.organs.length,2);}finally{s.cleanup();}});

test('idle previews retain every deformed procedural vertex instead of replacing them with sampled skin',()=>{const s=setup();try{const f=defaultFlora(),root=addFloraAsset(f,f.branches[0].id,'flora-bent-twig'),small=addFloraAsset(f,root.branch,'flora-tapered-twig',0,0,{organ:root.id,surface:{mesh:0,triangle:10,bary:[.2,.3,.5]}});root.morphs={'bend':1};small.scale=[.1,.1,.1];const e=s.editor;e.open(makePart('flora',{flora:f}));const check=()=>{for(const o of e.draft.flora.organs){const group=e.preview.children.find(g=>g.userData.floraOrgan===o.id);assert.ok(group,o.id);for(const mesh of group.children){const source=mesh.geometry.userData.floraSource;assert.deepEqual(Array.from(mesh.geometry.attributes.position.array),Array.from(Float32Array.from(floraDeformPositions(o,source))));}}};check();e.select({organ:root.id,branch:root.branch});e.controls.dispatchEvent({type:'dragging-changed',value:true});e.controls.object.position.x=.2;e.controls.dispatchEvent({type:'objectChange'});check();e.controls.dispatchEvent({type:'dragging-changed',value:false});check();e.undo();check();}finally{s.cleanup();}});

