 test('attachment targets appear during a sidebar drag and disappear when deselected',()=>{const s=setup();try{const e=s.editor,f=defaultFlora(),root=addFloraAsset(f,f.branches[0].id,'flora-bent-twig');e.open(makePart('flora',{flora:f}));e.deselect();e.beginAssetDrag('flora-elbow-branch');assert.ok(e.connections.children.some(m=>m.userData.floraMarkerKind==='attachment'));assert.equal(e.handles.visible,false);e.endAssetDrag();assert.equal(e.connections.children.length,0);e.select({organ:root.id,branch:root.branch});assert.ok(e.connections.children.every(m=>m.userData.floraMarkerKind==='section'));}finally{s.cleanup();}});

function gizmoRotate(s,angle){s.editor.setMode('rotate');const c=s.editor.controls;c.dispatchEvent({type:'dragging-changed',value:true});c.object.quaternion.setFromAxisAngle(new T.Vector3(0,0,1),angle);c.dispatchEvent({type:'objectChange'});c.dispatchEvent({type:'dragging-changed',value:false});}
function dragNode(s,mode,dx,dy,cancel=false){const e=s.editor;e.setMode(mode);const marker=e.handles.children.find(m=>m.userData.floraHandle.index===e.selection.index&&m.userData.floraHandle.branch===e.selection.branch)||e.handles.children[0],ndc=marker.getWorldPosition(new T.Vector3()).project(s.camera),event={button:0,clientX:(ndc.x+1)*400,clientY:(1-ndc.y)*300,preventDefault(){},stopImmediatePropagation(){}};for(const fn of s.canvas.listeners.pointerdown)fn(event);for(const fn of s.canvas.listeners.pointermove)fn({...event,clientX:event.clientX+dx,clientY:event.clientY+dy});for(const fn of s.canvas.listeners[cancel?'pointercancel':'pointerup'])fn({...event,clientX:event.clientX+dx,clientY:event.clientY+dy});}
