test('direct node movement carries the outgoing chain; rotation pivots at the selected node; scaling is uniform and undoable',()=>{const s=setup();try{const e=s.editor;e.open(s.part);const b=e.draft.flora.branches[0],id=b.id;e.select({branch:id,index:1});const points=structuredClone(b.points);dragNode(s,'translate',35,-20);let edited=e.draft.flora.branches.find(b=>b.id===id);assert.deepEqual(edited.points[0],points[0]);const delta=new T.Vector3(...edited.points[1]).sub(new T.Vector3(...points[1]));assert.ok(delta.length()>.01);for(let i=2;i<points.length;i++)assert.ok(new T.Vector3(...edited.points[i]).sub(new T.Vector3(...points[i])).distanceTo(delta)<1e-6);e.undo();e.select({branch:id,index:1});gizmoRotate(s,.4);edited=e.draft.flora.branches.find(b=>b.id===id);assert.deepEqual(edited.points[0],points[0]);assert.deepEqual(edited.points[1],points[1]);assert.notDeepEqual(edited.points[2],points[2]);assert.ok(edited.jointRotations[1]);e.undo();e.select({branch:id,index:1});const radius=e.draft.flora.branches[0].radii[1];dragNode(s,'scale',0,-30);assert.ok(e.draft.flora.branches[0].radii[1]>radius);e.undo();assert.equal(e.draft.flora.branches[0].radii[1],radius);e.select({branch:id,index:1});const original=JSON.stringify(e.draft);dragNode(s,'translate',25,15,true);assert.equal(JSON.stringify(e.draft),original);assert.equal(e.dragging,false);assert.equal(s.orbit.enabled,true);}finally{s.cleanup();}});
