test('near-bark surface drops snap gently and reuse the native part ghost geometry',()=>{
 const s=setup();try{
  const f=defaultFlora(),o=addFloraAsset(f,f.branches[0].id,'flora-bent-twig'),e=s.editor;e.open(makePart('flora',{flora:f}));s.camera.position.set(0,1,8);const mesh=e.pickTargets.children[0],positions=mesh.geometry.attributes.position,focus=new T.Vector3();for(let i=0;i<3;i++)focus.add(new T.Vector3().fromBufferAttribute(positions,i));focus.multiplyScalar(1/3).applyMatrix4(mesh.matrixWorld);s.camera.lookAt(focus);s.camera.updateMatrixWorld(true);e.beginAssetDrag('flora-ginkgo-leaf');
  const ray=new T.Raycaster(),hit=x=>{ray.setFromCamera(new T.Vector2(x/400-1,0),s.camera);return ray.intersectObjects(e.pickTargets.children,false).length>0;};let edge=400;assert.ok(hit(edge));while(hit(edge)&&edge<700)edge++;
  const event={clientX:edge+5,clientY:300,dataTransfer:{},preventDefault(){},stopPropagation(){}};assert.equal(hit(event.clientX),false);for(const fn of s.canvas.listeners.dragover)fn(event);assert.ok(e.dropTarget?.surface);assert.equal(e.dropTarget.organ,o.id);const geometry=e.ghost.children[0].children[0].geometry;
  for(const fn of s.canvas.listeners.dragover)fn({...event,clientY:305});assert.ok(e.dropTarget?.surface);assert.equal(e.ghost.children[0].children[0].geometry,geometry);
  for(const fn of s.canvas.listeners.dragover)fn({...event,clientX:edge+40});assert.equal(e.dropTarget,null);
 }finally{s.cleanup();}
});

