  const e=s.editor,p=makePart('flora',{flora:defaultFlora()}),event={button:0,clientX:650,clientY:450,preventDefault(){},stopPropagation(){},stopImmediatePropagation(){}};
  e.beginAssetPlacement('flora-elbow-branch',p);assert.equal(e.active,true);assert.equal(e.draft.flora.branches[0].anchor,true);assert.equal(e.draft.flora.organs.length,0);
  for(const fn of s.canvas.listeners.pointermove)fn(event);assert.ok(e.ghost);assert.equal(e.dropTarget.free,true);const expected=[...e.draft.position];
  for(const fn of s.canvas.listeners.pointerdown)fn(event);assert.equal(e.draft.flora.branches.length,1);assert.equal(e.draft.flora.branches[0].profile,'flora-elbow-branch');assert.deepEqual(e.draft.position,expected);assert.equal(e.ghost,null);assert.equal(s.orbit.enabled,true);
  e.undo();assert.equal(e.draft.flora.branches[0].anchor,true);e.undo(true);assert.equal(e.draft.flora.branches[0].profile,'flora-elbow-branch');
