test('part pickup waits for a valid connection and Escape cancels without adding or changing history',()=>{
 const s=setup();try{
  const e=s.editor;e.open(makePart('flora',{flora:defaultFlora()}));e.addAsset('flora-elbow-branch');const original=JSON.stringify(e.draft),root=e.draft.flora.branches[0];
  e.beginAssetPlacement('flora-stepped-branch');const invalid={button:0,clientX:-1000,clientY:-1000,preventDefault(){},stopPropagation(){},stopImmediatePropagation(){}};
  for(const fn of s.canvas.listeners.pointerdown)fn(invalid);assert.equal(JSON.stringify(e.draft),original);
  const target=e.connections.children.find(m=>m.userData.floraConnection.branch===root.id&&m.userData.floraConnection.at===1),ndc=target.position.clone().project(s.camera),event={...invalid,clientX:(ndc.x+1)*400,clientY:(1-ndc.y)*300};
  for(const fn of s.canvas.listeners.pointermove)fn(event);assert.ok(e.ghost);for(const fn of window.listeners.keydown)fn({key:'Escape',target:{},preventDefault(){},stopImmediatePropagation(){}});assert.equal(JSON.stringify(e.draft),original);assert.equal(e.ghost,null);
  e.beginAssetPlacement('flora-stepped-branch');for(const fn of s.canvas.listeners.pointerdown)fn(event);assert.equal(e.draft.flora.branches.length,2);assert.equal(e.draft.flora.branches[1].parent,root.id);e.undo();assert.equal(JSON.stringify(e.draft),original);e.undo();assert.equal(e.draft.flora.branches[0].anchor,true);
 }finally{s.cleanup();}
});

