test('widgets follow the active tool and selected branch, including after extension and deselection',()=>{
 const s=setup();try{const e=s.editor;e.open(s.part);assert.equal(e.widgets.children.length,0);
  const selected=e.selection.branch,other=e.draft.flora.branches.find(b=>!b.anchor&&b.id!==selected);
  e.setMode('scale');assert.equal(e.widgets.children.length,1);assert.equal(e.widgets.children[0].userData.floraWidget.selection.branch,selected);
  widgetDrag(s,'extend');assert.equal(e.controls.mode,'scale');assert.equal(e.widgets.children.length,1);
  e.select({branch:other.id,index:1});assert.equal(e.widgets.children.length,1);assert.equal(e.widgets.children[0].userData.floraWidget.selection.branch,other.id);
  e.setMode('rotate');assert.equal(e.widgets.children.length,0);assert.equal(e.controls.enabled,true);assert.equal(e.controls.getHelper().visible,true);assert.equal(e.controls.mode,'rotate');
  e.setMode('translate');assert.equal(e.widgets.children.length,0);e.deselect();for(const mode of ['rotate','scale','translate']){e.setMode(mode);assert.equal(e.widgets.children.length,0);}
 }finally{s.cleanup();}
});

test('selecting a trunk or branch exposes the whole plant joint network while widgets stay local',()=>{
 const s=setup();try{
  const e=s.editor,f=testPlant(),host=f.branches.find(b=>!b.anchor),assembly=addFloraAsset(f,host.id,'flora-forked-bough',.9);
  addFloraAsset(f,f.branches.filter(b=>!b.anchor)[1].id,'flora-forked-bough',.6);
  e.open(makePart('flora',{flora:f}));
  const branchIds=()=>new Set(e.handles.children.filter(m=>m.userData.floraMarkerKind==='joint').map(m=>m.userData.floraHandle.branch));
  const expected=new Set(f.branches.filter(b=>!b.anchor).map(b=>b.id));
  assert.deepEqual(branchIds(),expected);
  assert.ok(e.connections.children.some(m=>m.userData.floraConnection.organ===assembly.id));
  const other=f.branches.find(b=>!b.anchor&&b.id!==host.id);
  e.select({branch:other.id,index:1});assert.deepEqual(branchIds(),expected);
  e.setMode('rotate');assert.equal(e.widgets.children.length,0);assert.equal(e.controls.enabled,true);assert.equal(e.controls.getHelper().visible,true);assert.equal(e.controls.mode,'rotate');
  e.select({organ:assembly.id,branch:assembly.branch,socket:'joint:1'});assert.deepEqual(branchIds(),expected);
  assert.ok(e.connections.children.some(m=>m.userData.floraConnection.organ===assembly.id&&m.userData.floraConnection.socket==='joint:1'&&m.material.color.getHexString()==='ffd073'));
  assert.equal(e.connections.children.filter(m=>m.material.color.getHexString()==='ffd073').length,1);
  e.setMode('translate');assert.equal(e.widgets.children.length,0);
  e.select({branch:host.id,index:1});e.controls.dispatchEvent({type:'dragging-changed',value:true});e.controls.object.position.x+=.2;e.controls.dispatchEvent({type:'objectChange'});
  const marker=e.connections.children.find(m=>m.userData.floraConnection.organ===assembly.id&&m.userData.floraConnection.socket==='joint:1'),node=e.draft.flora.organs.find(o=>o.id===assembly.id),socket=floraSockets(node.asset).find(n=>n.id==='joint:1');
  const expectedPoint=new T.Vector3(...floraSocketPose(node,socket).point).applyMatrix4(floraOrganMatrix(e.draft.flora,node));
  assert.ok(marker.position.distanceTo(expectedPoint)<1e-6);
  e.controls.dispatchEvent({type:'dragging-changed',value:false});
  e.deselect();assert.equal(e.handles.children.length,0);assert.equal(e.connections.children.length,0);assert.equal(e.widgets.children.length,0);
 }finally{s.cleanup();}
});
