test('an attached object group base selects and edits the host joint as one undoable control',()=>{
 const s=setup();try{const f=defaultFlora(),parent=addFloraAsset(f,f.branches[0].id,'flora-basic-branch'),o=addFloraAsset(f,parent.id,'flora-forked-bough',1),e=s.editor;e.open(makePart('flora',{flora:f}));e.select({organ:o.id,branch:o.branch});assert.equal(e.handles.children.filter(m=>m.userData.floraMarkerKind==='part').length,0,'no whole-part box over the shared ball');e.select({organ:o.id,branch:o.branch,socket:'joint:0'});assert.deepEqual(e.selection,{branch:parent.id,index:1});
  const before=JSON.stringify(e.draft),c=e.controls;c.dispatchEvent({type:'dragging-changed',value:true});c.object.position.x+=.6;c.dispatchEvent({type:'objectChange'});c.dispatchEvent({type:'dragging-changed',value:false});const moved=e.draft.flora.organs.find(n=>n.id===o.id),root=floraSockets(o.asset).find(n=>n.id==='joint:0');assert.ok(new T.Vector3(...floraSocketPose(moved,root).point).applyMatrix4(floraOrganMatrix(e.draft.flora,moved)).distanceTo(floraCurve(e.draft.flora,parent.id).getPoint(1))<1e-7);assert.equal(e.draft.flora.branches.length,1);e.undo();assert.equal(JSON.stringify(e.draft),before);e.undo(true);
  e.beginAssetDrag('flora-basic-branch');assert.ok(!e.connections.children.some(m=>m.userData.floraConnection.organ===o.id&&m.userData.floraConnection.socket==='joint:0'),'shared base has one drop target');e.endAssetDrag();
 }finally{s.cleanup();}
});
